insert into public.topics (module_id, slug, title, summary, position, published) select id, 'css-selectors', 'CSS Selectors', 'How to target elements precisely with selectors.', 0, true from public.modules where level_id = 1 and title = 'CSS Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain css selectors in your own words.","Recognise and apply: a class selector (.card) can be reused on many elements.","Recognise and apply: an id selector (#hero) must be unique on the page.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers css selectors: how to target elements precisely with selectors. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a class selector (.card) can be reused on many elements. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that an id selector (#hero) must be unique on the page. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how css selectors fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.card { border: 1px solid #d9c27a; padding: 1rem; }
