insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain colours, backgrounds and typography in your own words.","Recognise and apply: contrast between text and background must stay readable.","Recognise and apply: font-family, size, weight and line-height shape readability.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers colours, backgrounds and typography: choosing readable colours, backgrounds and type. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that contrast between text and background must stay readable. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that font-family, size, weight and line-height shape readability. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how colours, backgrounds and typography fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', 'body { color: #1f2937; background: #fffdf5; font-family: Georgia, serif; }
