insert into public.topics (module_id, slug, title, summary, position, published) select id, 'css-grid-fundamentals', 'CSS Grid Fundamentals', 'Two-dimensional layout with rows and columns.', 0, true from public.modules where level_id = 1 and title = 'CSS Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain css grid fundamentals in your own words.","Recognise and apply: display: grid lets you place items in rows and columns at once.","Recognise and apply: grid-template-columns defines the track sizes of the grid.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers css grid fundamentals: two-dimensional layout with rows and columns. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that display: grid lets you place items in rows and columns at once. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that grid-template-columns defines the track sizes of the grid. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how css grid fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'css', '.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
