insert into public.topics (module_id, slug, title, summary, position, published) select id, 'variables-and-data-types', 'Variables and Data Types', 'Declaring variables and the basic data types.', 0, true from public.modules where level_id = 1 and title = 'JavaScript Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain variables and data types in your own words.","Recognise and apply: const is for values that will not be reassigned; let is for values that change.","Recognise and apply: strings, numbers, booleans, null, undefined, arrays and objects are the core types.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers variables and data types: declaring variables and the basic data types. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that const is for values that will not be reassigned; let is for values that change. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that strings, numbers, booleans, null, undefined, arrays and objects are the core types. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how variables and data types fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const academy = ''Nexora'';
