insert into public.topics (module_id, slug, title, summary, position, published) select id, 'operators-and-conditions', 'Operators and Conditions', 'Arithmetic, comparison and logical operators, and if/else decisions.', 0, true from public.modules where level_id = 1 and title = 'JavaScript Essentials' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain operators and conditions in your own words.","Recognise and apply: === checks value and type; == can coerce types and surprise you.","Recognise and apply: if / else if / else runs exactly one branch based on a condition.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers operators and conditions: arithmetic, comparison and logical operators, and if/else decisions. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that === checks value and type; == can coerce types and surprise you. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that if / else if / else runs exactly one branch based on a condition. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how operators and conditions fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const score = 8;
